-- ==============================================================================
-- MIGRATION: 20261010201500_fix_goat_image_storage_authorization.sql
-- Description: Targeted fix for Storage authorization functions and policies to support
-- 'farm/<farm_code>/...' paths generated by the website (e.g., 'farm/FARM-001/GOAT-008/174200_0.webp').
-- Fixes UUID casting failure on text farm_code strings while preserving strict farm ownership RLS.
-- ==============================================================================

BEGIN;

-- 1. Helper function: can_access_storage_farm_path
-- Updates authorization to safely evaluate both UUID and farm_code strings without casting exceptions.
CREATE OR REPLACE FUNCTION public.can_access_storage_farm_path(object_name TEXT)
RETURNS BOOLEAN AS $$
DECLARE
    v_prefix TEXT;
    v_target TEXT;
    v_user_id UUID;
    v_is_suspended BOOLEAN;
BEGIN
    -- Reject unauthenticated or empty requests immediately
    v_user_id := auth.uid();
    IF v_user_id IS NULL OR object_name IS NULL OR object_name = '' THEN
        RETURN FALSE;
    END IF;

    -- Check if user account is suspended
    SELECT p.is_suspended INTO v_is_suspended
    FROM public.profiles p
    WHERE p.id = v_user_id;

    IF v_is_suspended IS TRUE THEN
        RETURN FALSE;
    END IF;

    -- Super Admin bypass (only for authenticated, active super admins)
    IF public.is_super_admin() THEN
        RETURN TRUE;
    END IF;

    v_prefix := split_part(object_name, '/', 1);
    v_target := split_part(object_name, '/', 2);

    -- Pattern A: 'farm/<farm_code_or_uuid>/...'
    IF v_prefix = 'farm' AND v_target != '' THEN
        RETURN EXISTS (
            SELECT 1 FROM public.farms f
            WHERE (f.id::text = v_target OR f.farm_code = v_target)
              AND (
                  f.owner_id = v_user_id
                  OR f.id IN (
                      SELECT p.farm_id
                      FROM public.profiles p
                      WHERE p.id = v_user_id AND p.role = 'FARM_ADMIN'
                  )
              )
        );
    END IF;

    -- Pattern B: '<farm_code_or_uuid>/...' (root-level farm_code or farm_id)
    IF v_prefix != '' THEN
        RETURN EXISTS (
            SELECT 1 FROM public.farms f
            WHERE (f.id::text = v_prefix OR f.farm_code = v_prefix)
              AND (
                  f.owner_id = v_user_id
                  OR f.id IN (
                      SELECT p.farm_id
                      FROM public.profiles p
                      WHERE p.id = v_user_id AND p.role = 'FARM_ADMIN'
                  )
              )
        );
    END IF;

    RETURN FALSE;
EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp;

-- 2. Helper function: can_modify_storage_goat_image
CREATE OR REPLACE FUNCTION public.can_modify_storage_goat_image(object_name TEXT)
RETURNS BOOLEAN AS $$
BEGIN
    RETURN public.can_access_storage_farm_path(object_name);
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp;

-- 3. Execution Grants
-- Grant execute permissions strictly to authenticated users
GRANT EXECUTE ON FUNCTION public.can_access_storage_farm_path(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.can_modify_storage_goat_image(TEXT) TO authenticated;

-- Revoke execute permissions from anonymous/public callers
REVOKE EXECUTE ON FUNCTION public.can_access_storage_farm_path(TEXT) FROM anon, public;
REVOKE EXECUTE ON FUNCTION public.can_modify_storage_goat_image(TEXT) FROM anon, public;

-- 4. Verify / Update RLS Policies on storage.objects for goat-images
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "storage_goat_images_insert" ON storage.objects;
DROP POLICY IF EXISTS "storage_goat_images_update" ON storage.objects;
DROP POLICY IF EXISTS "storage_goat_images_delete" ON storage.objects;

CREATE POLICY "storage_goat_images_insert" ON storage.objects
    FOR INSERT TO authenticated
    WITH CHECK (
        bucket_id = 'goat-images'
        AND public.can_access_storage_farm_path(name)
    );

CREATE POLICY "storage_goat_images_update" ON storage.objects
    FOR UPDATE TO authenticated
    USING (
        bucket_id = 'goat-images'
        AND public.can_modify_storage_goat_image(name)
    )
    WITH CHECK (
        bucket_id = 'goat-images'
        AND public.can_modify_storage_goat_image(name)
    );

CREATE POLICY "storage_goat_images_delete" ON storage.objects
    FOR DELETE TO authenticated
    USING (
        bucket_id = 'goat-images'
        AND public.can_modify_storage_goat_image(name)
    );

COMMIT;
